def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add final field if we have one, or empty field for empty line
            if not fields:
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or the closing quote
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows
                        if i == n:
                            # End of line after closing quote - valid
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            # Comma after closing quote - valid
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < n:
                # Skip the comma
                i += 1

    return fields

